public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    Arrays.sort(arr);

    int removeCount = (int) Math.ceil(n / 10.0);
    int actualRemoveCount = Math.min(removeCount, n - removeCount - 1) / 2;

    int start = removeCount;
    int end = n - removeCount - 1;

    double sum = 0;
    for (int i = start; i <= end; i++) {
        sum += arr[i];
    }

    return sum / actualRemoveCount;
}

